@props(['options', 'placeholder'=>'Pilih opsi...', 'searchable'=>false, 'searchPlaceholder'=>'Cari...'])
<x-eoffice::manajemen-praktikum.ui.select-menu-styles />
<div x-data="{ open: false, value: '', search:'', options: {{ json_encode($options) }}, get filteredOptions(){return Object.fromEntries(Object.entries(this.options).filter(([key,label])=>String(label).toLocaleLowerCase('id').includes(this.search.trim().toLocaleLowerCase('id'))))}, get filteredEntries(){const entries=Object.entries(this.filteredOptions);return entries.every(([key])=>/^\d{2}$/.test(key))?entries.sort(([a],[b])=>a.localeCompare(b)):entries} }" x-modelable="value" {{ $attributes }} @click.outside="open=false" @keydown.escape.stop="open=false" style="position:relative">
    <button type="button" @click="open=!open;search='';@if($searchable)if(open)$nextTick(()=>$refs.optionSearch.focus())@endif" :aria-expanded="open" class="ta-select"><span x-text="options[String(value)] || @js($placeholder)"></span><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#666D80" stroke-width="2" style="transition:transform .2s" :style="open ? 'transform:rotate(180deg)' : ''"><path d="m6 9 6 6 6-6"/></svg></button>
    <div x-show="open" x-cloak x-transition.opacity.duration.150ms class="ta-options">
        @if($searchable)<div class="ta-option-search"><input type="search" x-ref="optionSearch" x-model="search" placeholder="{{ $searchPlaceholder }}" aria-label="{{ $searchPlaceholder }}" @click.stop @keydown.enter.prevent></div>@endif
        <template x-for="entry in filteredEntries" :key="entry[0]"><button type="button" class="ta-option" @click="value = entry[0] === 'true' ? true : (entry[0] === 'false' ? false : entry[0]); open=false" x-text="entry[1]" :class="String(value) === entry[0] ? 'selected' : ''" :aria-pressed="String(value) === entry[0]"></button></template>
        @if($searchable)<p x-show="Object.keys(filteredOptions).length===0" class="ta-option-empty">Data tidak ditemukan.</p>@endif
    </div>
</div>
